private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
  int result = i;
  while (bb.hasRemaining()) {
    byte b = bb.get();
    if ((b & 0x80) == 0) { // 1-byte character
      sb.append(Character.valueOf((char) b));
      result++;
    } else if ((b & 0xE0) == 0xC0) { // 2-byte character
      byte b2 = bb.get();
      int codePoint = (b & 0x1F) << 6 | (b2 & 0x3F);
      sb.append(Character.valueOf((char) codePoint));
      result += 2;
    } else if ((b & 0xF0) == 0xE0) { // 3-byte character
      byte b2 = bb.get();
      byte b3 = bb.get();
      int codePoint = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
      sb.append(Character.valueOf((char) codePoint));
      result += 3;
    } else if ((b & 0xF8) == 0xF0) { // 4-byte character
      // This is an invalid code point encoding.
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
  }
  return result;
}

