    // Check if the number of local variables is valid
    if (numLocal < 0) {
        throw new IllegalArgumentException("Number of local variables cannot be negative");
    }
    // Check if the number of stack elements is valid
    if (numStack < 0) {
        throw new IllegalArgumentException("Number of stack elements cannot be negative");
    }

    // Create a new stack map frame
    StackMapFrame frame = new StackMapFrame(offset, numLocal, numStack);
    // Add the new frame to the current frame array
    currentFrame.add(frame);
    // Return the index of the next element to be written in this frame
    return frame.getNextIndex();
}

