private TreeNode<T> rotateRight(TreeNode<T> node) {
	if (node == null) {
		throw new IllegalArgumentException("Node cannot be null");
	}

	TreeNode<T> parent = node.parent;
	TreeNode<T> leftChild = node.left;
	TreeNode<T> rightChild = node.right;

	// make rightChild the new parent of {@code node}
	if (rightChild != null) {
		rightChild.parent = node;
	}

	// make node a left child of its new parent
	node.parent = rightChild;
	node.right = rightChild;

	// make node a right child of its left child
	if (leftChild != null) {
		leftChild.parent = node;
		leftChild.right = node;
	}

	// make the new parent of {@code node} the right child of its current parent
	if (parent != null) {
		parent.right = node;
	}

	return parent;
}

