public void generateGraph(Graph target, Map resultMap) {
        // Check if the input is valid
        if (target == null || resultMap == null) {
            throw new IllegalArgumentException("Invalid input");
        }
        // Check if the target is undirected and bipartite
        if (!target.isUndirected() || !target.isBipartite()) {
            throw new UnsupportedOperationException("Not a valid bipartite graph");
        }
        // Get the degrees for each vertex in the graph
        Map<V, Integer> vertexDegrees = resultMap.getVertexDegrees(target);
        // Initialize the bipartition
        Map<String, List<V>> bipartition = new HashMap<>();
        // Iterate over the vertices in the graph
        for (V vertex : target.vertices()) {
            // Get the degree for the current vertex
            int degree = vertexDegrees.getOrDefault(vertex, 0);
            // Check if the vertex is in the left or right side of the bipartition
            if (degree % 2 == 0) {
                // Add the vertex to the left side
                bipartition.computeIfAbsent("left", s -> new ArrayList<>()).add(vertex);
            } else {
                // Add the vertex to the right side
                bipartition.computeIfAbsent("right", s -> new ArrayList<>()).add(vertex);
            }
        }
        // Add the edges to the graph
        for (V vertex : bipartition.get("left")) {
            for (V neighbor : bipartition.get("right")) {
                target.addEdge(vertex, neighbor);
            }
        }
        // Add the result to the map
        resultMap.put("bipartition", bipartition);
    }

