public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {

    // Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the parameterized type
    ParameterizedType parameterizedType = (ParameterizedType) genericType;

    // Get the type variable
    TypeVariable<?>[] typeVariables = parameterizedType.getActualTypeArguments();

    // Check if the type variables are assignable to the target type
    if (!typeVariablesAssignableToTargetType(typeVariables, targetType)) {
        return null;
    }

    // Resolve the type variables
    Class<?>[] typeArguments = resolveTypeArguments(typeVariables, targetType);

    return typeArguments;
}

private static boolean typeVariablesAssignableToTargetType(TypeVariable<?>[] typeVariables, Class<?> targetType) {
    for (TypeVariable<?> typeVariable : typeVariables) {
        if (!typeVariable.getBounds().get(0).equals(targetType)) {
            return false;
        }
    }
    return true;
}

