public Map<String, List<String>> diffStructure(String tableName, Mappings mappings) {
	// Initialize output structure
	Map<String, List<String>> output = new HashMap<>();

	// Get the mapping for the table specified in the input
	Map<String, Object> mapping = mappings.getMapping(tableName);

	// If the mapping does not exist, return an empty map
	if (mapping == null) {
		return output;
	}

	// Get the field names from the mapping
	List<String> fields = mapping.keySet()
		.stream()
		.map(String::valueOf)
		.collect(Collectors.toList());

	// If there are no fields in the mapping, return an empty map
	if (fields.isEmpty()) {
		return output;
	}

	// Iterate over all fields in the mapping and check if they exist in the input mappings
	for (String field : fields) {
		if (!mappings.containsField(field)) {
			// If the field does not exist in the input mappings, add it to the output
			output.put(field, new ArrayList<>());
		}
	}

	return output;
}

