protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start == 0) {
        start = 1;
    }
    if (end == 0) {
        end = FETCH_DATA_DURATION.getDecrement();
    }
    while (start < end) {
        long segmentDuration = Math.min(end - start, FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(start, start + segmentDuration));
        start += segmentDuration;
    }
    return timeRanges;
}

