public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if(str == null || session == null || lb == null){
        throw new NullPointerException("Input arguments cannot be null");
    }
    lb.reset();
    final int strLen = str.length();
    try{
        final ByteBuf buf = lb.byteBuf;
        for(int i = 0; i < strLen; i++){
            final char ch = str.charAt(i);
            if((ch >= 0x0 && ch <= 0x7F) || ch == 0xFFFE || ch == 0xFFFF){
                buf.writeByte(ch);
            } else{
                final String strVar = String.valueOf(ch);
                buf.writeBytes(strVar.getBytes("UTF-8"));
            }
        }
    } catch(final UnsupportedEncodingException e){
        throw new RuntimeException("Failed to convert char sequence to utf-8 bytes", e);
    }
    return lb;
}

public void removeFromTreeEdgeList() {
    if (head != null && prev != null) {
        // Remove this edge from the head doubly linked list
        head.next = this.next;
        if (this.next != null) {
            this.next.prev = head;
        }
        // Remove this edge from the prev doubly linked list
        prev.next = this.next;
        if (this.next != null) {
            this.next.prev = prev;
        }
    } else {
        // One or both of head and prev are null, which means this edge is not
        // part of either doubly linked list.
        throw new IllegalStateException("Edge is not part of any doubly linked list");
    }
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value.contains("${")) {
        // extract the variable name and its replacement value
        Pattern pattern = Pattern.compile("\\$\\{([a-zA-Z0-9_]+)\\}");
        Matcher matcher = pattern.matcher(value);
        if (matcher.find()) {
            String variable = matcher.group(1);
            String replacement = System.getProperty(variable, "");
            value = value.replace(matcher.group(0), replacement);
        }
    }
    return value;
}

protected void appendDetail(StringBuffer buffer, String fieldName, int[] array) {
