  for (int shift = 0; shift < 64; shift += 7) {
    final byte b = readRawByte();
    if (b == 0) {
      throw new IOException("Invalid LEB128 encoding");
    }
    result |= (long)(b & 0x7F) << shift;
    if ((b & 0x80) == 0) {
      return result;
    }
  }
  throw new IOException("LEB128 value too long");
}

