protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Invalid input. Source vertex, target vertex, and edge cannot be null.");
    }

    /*
     * Check if the edge is already present in the index.
     * If it is, simply return without adding it again.
     */
    if (this.edges.contains(e)) {
        return;
    }

    /*
     * Add the edge to the index.
     */
    this.edges.add(e);

    /*
     * Update the source vertex's outgoing edge set.
     */
    sourceVertex.getOutgoingEdges().add(e);

    /*
     * Update the target vertex's incoming edge set.
     */
    targetVertex.getIncomingEdges().add(e);
}

