Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    double width = box.getWidth();
    double height = box.getHeight();
    double halfWidth = width / 2.0;
    double halfHeight = height / 2.0;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMaxY(), halfWidth, halfHeight);
    Box2D rightBox = new Box2D(box.getMinX() + halfWidth, box.getMaxY(), halfWidth, halfHeight);
    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    int currentSize = getSize();
    if (size > 0) {
        if (size + currentSize > capacity) {
            capacity = size + currentSize + 1;
            byte[] newData = new byte[capacity];
            System.arraycopy(data, 0, newData, 0, currentSize);
            data = newData;
        }
    }
}

