public void readFrom(final java.io.InputStream in) throws java.io.IOException {
        // Clear and reset the buffer
        this.buffer.setPosition(0);
        this.buffer.setLimit(0);

        // Read from the input stream and write to the buffer
        java.nio.ByteBuffer buffer = java.nio.ByteBuffer.allocate(1024);
        while (in.read(buffer) > 0) {
            buffer.flip();
            this.buffer.put(buffer);
            buffer.clear();
        }
    }

