public static Object findFirstMatch(Collection source, Collection candidates) {
	// Check if source is null or empty
	if (source == null || source.isEmpty()) {
		return null;
	}
	// Check if candidates is null or empty
	if (candidates == null || candidates.isEmpty()) {
		return null;
	}

	// Iterate through every element in source
	for (Object element : source) {
		// Check if the element is present in candidates
		if (candidates.contains(element)) {
			// If present, return the element
			return element;
		}
	}

	// If no element in candidates is present in source, return null
	return null;
}

