public int removeUnusedNodes() {
   int numNodesRemoved = 0; // tracks the number of nodes removed

   // Iterate through the categories in the tree, starting from the root
   Category rootCategory = this.rootCategory;
   if (rootCategory != null) {
      removeUnusedNodesHelper(rootCategory, numNodesRemoved);
   }

   return numNodesRemoved;
}

private void removeUnusedNodesHelper(Category currentCategory, int numNodesRemoved) {
   // Check if the current category is inactive, if so, remove it
   if (!currentCategory.isActive()) {
      // Remove the current category from its parent's children
      Category parentCategory = currentCategory.getParent();
      if (parentCategory != null) {
         parentCategory.getChildren().remove(currentCategory);
      }

      // Remove the current category and all of its children from the tree
      removeSubtree(currentCategory);
      numNodesRemoved++;
   }

   // Recursively remove unused nodes from each child of the current node
   for (Category childCategory : currentCategory.getChildren()) {
      removeUnusedNodesHelper(childCategory, numNodesRemoved);
   }
}

private void removeSubtree(Category currentRoot) {
   // Recursively traverse the subtree and remove all of its nodes
   Queue<Category> toRemove = new LinkedList<>();
   Queue<Category> toVisit = new LinkedList<>();
   toVisit.add(currentRoot);

   while (!toVisit.isEmpty()) {
      Category current = toVisit.remove();
      toRemove.add(current);

      // Recursively traverse the children of the current node
      for (Category child : current.getChildren()) {
         toVisit.add(child);
      }
   }

   while (!toRemove.isEmpty()) {
      Category current = toRemove.remove();
      currentRoot.getChildren().remove(current);
      currentRoot.setParent(null);
   }
}

