public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    if (charBuffer == null || charBuffer.length < 0) {
        throw new IllegalArgumentException("Invalid char buffer");
    }
    ConstantPoolEntry constantPoolEntry = classFileBuffer[constantPoolEntryIndex];
    if (constantPoolEntry.tag != Tag.UTF8.tag) {
        throw new IllegalArgumentException("Invalid constant pool entry type");
    }
    Utf8Info utf8Info = (Utf8Info) constantPoolEntry;
    int length = utf8Info.length;
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("Char buffer too small");
    }
    System.arraycopy(utf8Info.bytes, 0, charBuffer, 0, length);
    return new String(charBuffer, 0, length);
}

private static char decodeHexNibble(final char c) {
    if (c >= '0' && c <= '9') {
        return (char) (c - '0');
    } else if (c >= 'a' && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if (c >= 'A' && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

