private String parseToken(final char[] terminators) {
  // Initialization of variables
  String token = "";
  int index = 0;

  // Iterate through the input string and parse out each character
  while (index < terminators.length) {
    // If a terminator character is encountered, break out of the loop
    if (terminators[index] == terminators) {
      break;
    }

    // Otherwise, add the character to the token
    token += terminators[index];
    index++;
  }

  // Return the parsed token
  return token;
}

