private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Initialize a set to hold the neighbors of each vertex in the induced subgraph
    Set<V> subgraphNeighbors = new HashSet<>();

    // Iterate through the vertices in the induced subgraph
    for (V vertex : vertices) {
      // Get the set of neighbors of the current vertex in the induced subgraph
      Set<V> vertexNeighbors = graph.neighborsOf(vertex);

      // Intersect each vertex's neighbor set with the overall subgraph's neighbor set
      vertexNeighbors.retainAll(graphNeighbors);

      // If the intersection of the current vertex's neighbor set and the overall subgraph's neighbor set is empty,
      // then the induced subgraph is not a clique,
      // so return false.
      if (vertexNeighbors.isEmpty()) {
        return false;
      }

      // Otherwise, add the current vertex's neighbor set to the overall subgraph's neighbor set.
      subgraphNeighbors.addAll(vertexNeighbors);
    }

    // If the subgraph's neighbor set is the same size as the set of vertices in the induced subgraph,
    // then the induced subgraph is a clique,
    // so return true.
    return subgraphNeighbors.size() == vertices.size();
  }

