private void Pop(string descriptor)
{
    // Check if the descriptor is a method descriptor
    if (descriptor.StartsWith("("))
    {
        // Parse the argument type descriptors from the method descriptor
        string[] argumentTypeDescriptors = descriptor.Substring(1, descriptor.LastIndexOf(")")).Split(',');

        // Pop the argument types from the output frame stack
        foreach (string argumentTypeDescriptor in argumentTypeDescriptors)
        {
            switch (argumentTypeDescriptor)
            {
                case "I":
                    PopInt();
                    break;
                case "J":
                    PopLong();
                    break;
                case "F":
                    PopFloat();
                    break;
                case "D":
                    PopDouble();
                    break;
                default:
                    throw new ArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    }
    else
    {
        // Pop the abstract type from the output frame stack
        switch (descriptor)
        {
            case "I":
                PopInt();
                break;
            case "J":
                PopLong();
                break;
            case "F":
                PopFloat();
                break;
            case "D":
                PopDouble();
                break;
            default:
                throw new ArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

