public static String applyRelativePath(String path, String relativePath) {
String newPath = path;
for (String segment : relativePath.split("/")) {
if (segment.equals("..")) {
newPath = newPath.substring(0, newPath.lastIndexOf("/"));
} else if (!segment.equals(".")) {
newPath += "/" + segment;
}
}
return newPath;
}

