public static String[] toNoNullStringArray(Object[] array) {
    if (array == null || array.length == 0) {
      return new String[0];
    }
    ArrayList<String> list = new ArrayList<>();
    for (Object element : array) {
      if (element != null && element instanceof String) {
        list.add((String) element);
      }
    }
    return list.toArray(new String[list.size()]);
  }

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int extensionIndex = filename.lastIndexOf('.');
    if (extensionIndex != -1) {
        int extensionSeparatorIndex = indexOfLastSeparator(filename);
        if (extensionSeparatorIndex != -1 && extensionSeparatorIndex >= extensionIndex) {
            return -1;
        }
    }
    return extensionIndex;
}

public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastUnix = filename.lastIndexOf('/');
    int lastWindows = filename.lastIndexOf('\\');
    return Math.max(lastUnix, lastWindows);
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Check if the current time is greater than the expiration threshold
    if (timestamp > expiredThreshold) {
        // If the current time is greater than the expiration threshold, return true
        // to indicate that the metrics should be removed from cache
        return true;
    }
    // If the current time is less than the expiration threshold, return false
    // to indicate that the metrics should NOT be removed from cache
    return false;
}

