public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null || index < 0 || index + substring.length() > str.length()) {
        return false; // invalid input, return false
    }
    return str.subSequence(index, index + substring.length()).equals(substring);
}

protected void append(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("Append failed: Event cannot be null");
    }

    if (connectedClients.isEmpty()) {
        throw new IllegalStateException("Append failed: No connected clients");
    }

    String message = event.getFormattedMessage();
    if (message == null) {
        throw new IllegalStateException("Append failed: Message cannot be null");
    }

    for (Client client : connectedClients) {
        String username = client.getUsername();
        if (username == null) {
            throw new IllegalStateException("Append failed: Username cannot be null");
        }

        String clientMessage = String.format("%s: %s", username, message);
        client.writeMessage(clientMessage);
    }
}

