public int readTag() throws IOException {
    int tag = 0;
    if (inputStream.available() >= 3) {
        tag = (inputStream.read() & 0xFF) << 24;
        tag |= (inputStream.read() & 0xFF) << 16;
        tag |= (inputStream.read() & 0xFF) << 8;
        tag |= (inputStream.read() & 0xFF);
    }
    return tag;
}

